def task2_plot_requested(alias: str, *, essential: bool = False, debug: bool = False) -> bool:
    if debug:
        return create_debug_plots and task2_plot_enabled(alias)
    if essential:
        return (create_plots or create_essential_plots) and task2_plot_enabled(alias)
    return create_plots and task2_plot_enabled(alias)


def resolve_task2_plot_alias(save_path: str, alias: str | None = None) -> str | None:
    if alias is not None:
        return alias if alias in TASK2_PLOT_ALIASES else None

    stem = os.path.splitext(os.path.basename(str(save_path)))[0].lower()
    stem = re.sub(r"^\d+_", "", stem)
    if stem in TASK2_PLOT_ALIASES:
        return stem
    for prefix, mapped_alias in TASK2_PLOT_PREFIX_ALIASES:
        if stem.startswith(prefix):
            return mapped_alias
    for pattern, mapped_alias in TASK2_PLOT_REGEX_ALIASES:
        if pattern.match(stem):
            return mapped_alias
    return None

def apply_task2_plot_catalog_modes() -> None:
    global create_plots, create_essential_plots, create_debug_plots, save_plots, create_pdf
    if not task2_plot_status_by_alias:
        return
    create_plots = create_plots and task2_plot_enabled("usual_suite")
    create_essential_plots = create_essential_plots and task2_plot_enabled("essential_suite")
    create_debug_plots = create_debug_plots and task2_plot_enabled("debug_suite")
    save_plots = bool(create_plots or create_essential_plots or create_debug_plots)
    create_pdf = False  # Runtime plots are strictly PNG-only; FINAL PDFs are standalone.


def _coerce_config_value(value, value_type, default):
    """Coerce a config value to value_type, returning default on failure."""
    if value is None:
        return default

    try:
        return value_type(value)
    except (TypeError, ValueError):
        return default


def _append_or_replace_dataframe_columns(
    base_df: pd.DataFrame,
    columns: dict[str, object],
    *,
    defragment: bool = True,
) -> pd.DataFrame:
    """Append or replace dataframe columns in one batch to avoid fragmentation."""
    if not columns:
        return base_df
    column_frame = pd.DataFrame(
        {
            column_name: pd.Series(values, index=base_df.index)
            for column_name, values in columns.items()
        },
        index=base_df.index,
    )
    existing_columns = [column_name for column_name in column_frame.columns if column_name in base_df.columns]
    if existing_columns:
        base_df = base_df.drop(columns=existing_columns)
    combined_df = pd.concat([base_df, column_frame], axis=1)
    return combined_df.copy() if defragment else combined_df


def _coerce_config_bool(value: object, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"1", "true", "yes", "on"}:
            return True
        if normalized in {"0", "false", "no", "off"}:
            return False
    return bool(value)

def _coerce_figsize(value: object, default: tuple[float, float]) -> tuple[float, float]:
    if value is None:
        return default
    if isinstance(value, (tuple, list)) and len(value) == 2:
        try:
            return (float(value[0]), float(value[1]))
        except (TypeError, ValueError):
            return default
    if isinstance(value, str):
        raw_text = value.strip()
        if not raw_text:
            return default
        try:
            parsed = ast.literal_eval(raw_text)
        except (ValueError, SyntaxError):
            parsed = tuple(part.strip() for part in raw_text.replace("x", ",").split(",") if part.strip())
        return _coerce_figsize(parsed, default)
    return default


def _load_task2_calibration_subsample_config(config_path: Path, station_id: str) -> dict[str, object]:
    """Load the river config and resolve nested station-specific values."""
    if not config_path.exists():
        raise FileNotFoundError(
            "Task 2 calibration-subsample config is required but missing: "
            f"{config_path}"
        )
    with config_path.open("r", encoding="utf-8") as handle:
        raw_config = yaml.safe_load(handle) or {}
    if not isinstance(raw_config, dict):
        raise ValueError(f"Task 2 calibration-subsample config must be a YAML mapping: {config_path}")

    station_specific_keys = {
        "min",
        "max",
        "left",
        "right",
        "qsum_left",
        "qsum_right",
        "tsum_left",
        "tsum_right",
    }
    station_index = int(station_id)

    def _resolve(value: object, key: str | None = None) -> object:
        if isinstance(value, dict):
            return {nested_key: _resolve(nested_value, nested_key) for nested_key, nested_value in value.items()}
        if key in station_specific_keys and isinstance(value, list):
            if station_index >= len(value):
                raise ValueError(
                    f"Calibration river config key {key!r} has no value for station {station_id}."
                )
            return value[station_index]
        return value

    return _resolve(raw_config)


def _require_task2_calibration_config_keys(
    calibration_config: dict[str, object],
    required_keys: Iterable[str],
) -> None:
    missing = [key for key in required_keys if key not in calibration_config]
    if missing:
        raise KeyError(
            "Task 2 calibration-subsample config is missing required hard-filter keys: "
            + ", ".join(missing)
        )


