def safe_move(source_path: str, dest_path: str) -> str:
    """Move *source_path* to *dest_path* with explicit diagnostics on failure."""
    try:
        return shutil.move(source_path, dest_path)
    except OSError as exc:
        print(f"Error moving '{source_path}' to '{dest_path}': {exc}")
        raise


def _track_figure(fig: mpl.figure.Figure) -> mpl.figure.Figure:
    fig_number = getattr(fig, "number", None)
    if fig_number is None:
        return fig
    if fig_number not in _OPEN_FIGURE_IDS:
        _OPEN_FIGURE_IDS.append(fig_number)
    while len(_OPEN_FIGURE_IDS) > MAX_OPEN_FIGURES:
        stale_fig_number = _OPEN_FIGURE_IDS.pop(0)
        _ORIGINAL_PLT_CLOSE(stale_fig_number)
    return fig

def _guarded_figure(*args, **kwargs):
    return _track_figure(_ORIGINAL_PLT_FIGURE(*args, **kwargs))

def _guarded_subplots(*args, **kwargs):
    fig, axes = _ORIGINAL_PLT_SUBPLOTS(*args, **kwargs)
    _track_figure(fig)
    return fig, axes

def _guarded_close(*args, **kwargs):
    target = args[0] if args else kwargs.get("fig", None)
    result = _ORIGINAL_PLT_CLOSE(*args, **kwargs)
    if target in (None, "all"):
        _OPEN_FIGURE_IDS.clear()
    elif isinstance(target, mpl.figure.Figure):
        fig_number = getattr(target, "number", None)
        if fig_number in _OPEN_FIGURE_IDS:
            _OPEN_FIGURE_IDS.remove(fig_number)
    elif isinstance(target, int) and target in _OPEN_FIGURE_IDS:
        _OPEN_FIGURE_IDS.remove(target)
    return result



def save_plot_figure(
    save_path: str,
    fig: mpl.figure.Figure | None = None,
    alias: str | None = None,
    **savefig_kwargs,
) -> None:
    """Save one runtime plot as PNG."""
    plot_alias = resolve_task2_plot_alias(save_path, alias=alias)
    if plot_alias is not None and not task2_plot_enabled(plot_alias):
        return
    target_fig = fig if fig is not None else plt.gcf()
    os.makedirs(os.path.dirname(save_path), exist_ok=True)
    target_fig.savefig(save_path, **savefig_kwargs)





def is_calibration_metadata_column(column_name: str) -> bool:
    return bool(CALIBRATION_METADATA_PATTERN.match(column_name))

def should_drop_calibration_metadata_field(column_name: str) -> bool:
    """
    Keep calibration metadata CSV schema strictly scoped to:
      - filename_base
      - execution_timestamp
      - param_hash
      - P*_s*_{Q_B,Q_F,Q_FB_coeffs(__N),Q_TDIF_coeffs(__N),Q_sum,T_sum,T_dif,T_slew_*}
    """
    if column_name in ("filename_base", "execution_timestamp", "param_hash"):
        return False
    return not is_calibration_metadata_column(column_name)

def _resolve_station_mode(raw, station_id: str, default: str = "make") -> str:
    """Resolve a calibration-mode config value for a specific station.

    raw may be:
      - a scalar string ("make" / "file" / null) → returned as-is for every station
      - a list [MINGO00_value, MINGO01_value, ...] → indexed by int(station_id);
        missing indices (list too short) and None entries fall back to default.
    """
    station_index = int(station_id)
    if isinstance(raw, list):
        if station_index < len(raw):
            v = raw[station_index]
            return v if v is not None else default
        return default
    return raw if raw is not None else default

def extract_calibration_metadata(
    metadata: dict[str, object],
    remove_from_source: bool = True,
) -> dict[str, object]:
    extracted: dict[str, object] = {}
    for key in ("filename_base", "execution_timestamp", "param_hash"):
        if key in metadata:
            extracted[key] = metadata[key]

    for key in list(metadata.keys()):
        if not isinstance(key, str):
            continue
        if not is_calibration_metadata_column(key):
            continue
        extracted[key] = metadata[key]
        if remove_from_source:
            metadata.pop(key, None)

    return extracted


